#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class WorldBossAuthorityLocalClientTests {
  static JObject Trace(int i)=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/WorldBossRail-20261002/AuthorityConsumer/hono-traces.json"))["traces"][i];
  static JObject Read(int i)=>(JObject)Trace(i)["response"];
  static JObject Definition()=>(JObject)Read(0)["journal"]["rail"]["definition"];
  static JObject Profile()=>(JObject)Read(0)["journal"]["geometry"]["profile"];
  static WorldBossAuthorityLocalClient Open(int i=0)=>new WorldBossAuthorityLocalClient(Read(i),Definition(),Profile(),"trial","a","health-run","train");
  static WorldBossAuthoritySnapshot Snapshot(JObject read)=>new WorldBossAuthoritySnapshot(read,Definition(),Profile(),"trial","health-run","train");
  static void Apply(WorldBossAuthorityLocalClient c,int i)=>c.ApplyRead(Read(i),(string)Trace(i)["cacheControl"],(string)Trace(i)["responseTransport"]);
  static WorldBossAuthorityRequest Start(WorldBossAuthorityLocalClient c){c.PreviewRoute("p1r1","RIGHT");return c.ConfirmPreview("route");}
  static void Ack(WorldBossAuthorityLocalClient c,WorldBossAuthorityRequest r,int i=1)=>c.AcceptAcknowledgement(r,Read(i),(string)Trace(i)["cacheControl"],(string)Trace(i)["responseTransport"]);
  static WorldBossAuthorityLocalClient Restore(string json)=>WorldBossAuthorityLocalClient.RestoreLocal(json,Definition(),Profile(),"trial","a","health-run","train");
  static void Equal(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b));
  [TestCase(0)][TestCase(3)][TestCase(8)][TestCase(9)][TestCase(10)][TestCase(13)]
  public void ActualHonoReadSnapshotsRemainExactAndImmutable(int i){var raw=Read(i);var s=Snapshot(raw);Equal(raw,s.Capture());raw["health"]["health"]["hp"]=0;Assert.AreNotEqual(0,s.Hp);var copy=s.Capture();copy["journal"]["ownerRevision"]=0;Assert.Greater(s.JournalRevision,0);}
  [TestCase(4)][TestCase(5)][TestCase(6)][TestCase(7)][TestCase(12)]
  public void ActualHonoErrorTracesRetainStatusAndCode(int i){var t=Trace(i);var e=new WorldBossAuthorityError((int)t["httpStatus"],(JObject)t["response"]);Assert.AreEqual((int)t["httpStatus"],e.HttpStatus);Equal(t["response"],e.Capture());}
  [Test] public void OneInputEmitsOriginalHeadersKeyAndBodyOnce(){using var c=Open();int n=0;c.Bind(r=>{n++;var actual=r.Capture();var expected=(JObject)Trace(1)["request"].DeepClone();expected.Remove("authenticatedTrialAccount");Equal(expected,actual);Assert.IsFalse(r.Headers.ContainsKey("Authorization"));},null);var request=Start(c);Assert.AreEqual(1,n);Equal(Trace(1)["request"]["body"],request.Body);var body=request.Body;body["expectedRevision"]=999;Assert.AreEqual(1,(long)request.Body["expectedRevision"]);}
  [Test] public void AckDoesNotPublishRouteOrHealthBeforeRead(){using var c=Open();var r=Start(c);Ack(c,r);Assert.AreEqual("ENTRY",(string)c.State.Geometry.Capture()["selectedRoute"]);Assert.AreEqual(1,c.State.Rail.Revision);Assert.AreEqual(1000,c.State.Hp);Assert.IsTrue(c.AwaitingRead);Assert.Throws<InvalidOperationException>(()=>c.PreviewRoute("p1r1","LEFT"));Apply(c,3);Assert.AreEqual("RIGHT",(string)c.State.Geometry.Capture()["selectedRoute"]);Assert.AreEqual(2,c.State.JournalRevision);Assert.IsNull(c.PendingRequest);}
  [Test] public void PendingHealthAndEvasionPreserveIndependentRevisionsAndOriginalReplay(){using var c=Open();var r=Start(c);Ack(c,r);Apply(c,3);int emitted=0;c.Bind(_=>emitted++,null);Apply(c,8);Assert.AreEqual("PENDING_HEALTH",c.State.ProcessingStatus);Assert.AreEqual(1000,c.State.Hp);Assert.AreEqual(10,c.State.JournalRevision);Assert.AreEqual(3,c.State.Rail.Revision);Assert.AreEqual(1,c.State.HealthRevision);Apply(c,9);Assert.AreEqual("APPLIED",c.State.ProcessingStatus);Assert.AreEqual(1,c.State.HealthRevision);Assert.AreEqual(2,c.State.ShieldRevision);Apply(c,10);Assert.AreEqual(0,emitted);Equal(r.Capture(),c.ReplayOriginal("route").Capture());Assert.AreEqual(1,emitted);Ack(c,r,11);}
  [Test] public void PartialShieldConsumesOriginalHpReceiptWithoutLocalAdjudication(){using var c=Open(13);Assert.AreEqual(740,c.State.Hp);Assert.AreEqual(2,c.State.HealthRevision);Assert.AreEqual(2,c.State.ShieldRevision);var raw=c.State.Capture();Assert.AreEqual("360",(string)raw["health"]["receipt"]["resolvedDamage"]);Assert.AreEqual(100,(long)raw["health"]["receipt"]["absorbed"]);Assert.AreEqual(17000,(long)raw["health"]["receipt"]["resolvedAtMs"]);Assert.AreEqual(15500,(long)raw["journal"]["geometry"]["attackResult"]["observedAtMs"]);Equal(Read(13),raw);}
  [Test] public void JournalHeaderAndRailBodyRevisionAreNotInterchanged(){var body=(JObject)Trace(1)["request"]["body"].DeepClone();body["expectedRevision"]=3;body["commandId"]="fresh";var r=new WorldBossAuthorityRequest("trial","LOCAL_GEO",body,10);Assert.AreEqual("10",r.Headers["X-World-Journal-Revision"]);Assert.AreEqual(3,(long)r.Body["expectedRevision"]);}
  [Test] public void TimeoutAndUnavailableRetryKeepExactOriginalRequest(){using var c=Open();var r=Start(c);Equal(r.Capture(),c.RetryOriginal().Capture());c.AcceptFailure(r,503,new JObject{["accepted"]=false,["errorCode"]="producer_unavailable"},"no-store",WorldBossAuthorityRequest.Version);Assert.IsTrue(c.LastError.PreserveOriginalRetry);Equal(r.Capture(),c.RetryOriginal().Capture());Assert.AreEqual(1,c.State.JournalRevision);}
  [TestCase(401)][TestCase(403)] public void RevokedAuthenticationBlocksRetryUntilRead(int status){using var c=Open();var r=Start(c);c.AcceptFailure(r,status,new JObject{["accepted"]=false,["errorCode"]="forbidden"},"no-store",WorldBossAuthorityRequest.Version);Assert.Throws<InvalidOperationException>(()=>c.RetryOriginal());Equal(r.Capture(),c.OriginalForRetry().Capture());Apply(c,0);Assert.IsFalse(c.AuthenticationBlocked);Equal(r.Capture(),c.RetryOriginal().Capture());}
  [TestCase(true)][TestCase(false)] public void ConflictRequiresReadAndReconcilesOriginalPresence(bool present){using var c=Open();var r=Start(c);c.AcceptFailure(r,409,(JObject)Trace(5)["response"],"no-store",WorldBossAuthorityRequest.Version);Assert.Throws<InvalidOperationException>(()=>c.RetryOriginal());Apply(c,present?3:0);Assert.IsNull(c.PendingRequest);Assert.IsFalse(c.AwaitingRead);Equal(r.Capture(),c.ReplayOriginal("route").Capture());}
  [TestCase(0)][TestCase(1)][TestCase(2)] public void PendingAckAndAppliedCachesRequireFreshReadAfterRestore(int stage){using var c=Open();var r=Start(c);if(stage>0)Ack(c,r);if(stage>1){Apply(c,3);Apply(c,9);}using var restored=Restore(c.CaptureLocal());Assert.IsTrue(restored.AwaitingRead);Assert.Throws<InvalidOperationException>(()=>restored.PreviewRoute("p1r1","LEFT"));Equal(c.State.Capture(),restored.State.Capture());if(stage<2){Equal(r.Capture(),restored.OriginalForRetry().Capture());Apply(restored,3);Assert.IsNull(restored.PendingRequest);}else{Apply(restored,10);Equal(r.Capture(),restored.ReplayOriginal("route").Capture());}Assert.IsFalse(restored.CaptureLocal().Contains("Authorization"));}
  [TestCase("version")][TestCase("source")][TestCase("hp")][TestCase("pending")][TestCase("hash")]
  public void InvalidReadCannotPartiallyPublish(string bad){using var c=Open();var before=c.CaptureLocal();var raw=Read(9);switch(bad){case "version":raw["transportVersion"]="old";break;case "source":raw["health"]["receipt"]["sourceJournalRevision"]=1;break;case "hp":raw["health"]["health"]["hp"]=1001;break;case "pending":raw["health"]["processingStatus"]="PENDING_HEALTH";break;case "hash":raw["journal"]["entries"][1]["previousHash"]=new string('0',64);break;}Assert.Throws<ArgumentException>(()=>c.ApplyRead(raw,"no-store",WorldBossAuthorityRequest.Version));Assert.AreEqual(before,c.CaptureLocal());}
  [TestCase("journal")][TestCase("receipt")][TestCase("headers")]
  public void InvalidAcknowledgementCannotClearPending(string bad){using var c=Open();var r=Start(c);var before=c.CaptureLocal();var a=Read(1);if(bad=="journal")a["requestJournalRevision"]=2;if(bad=="receipt")a["receipt"]["route"]="LEFT";Assert.Throws<ArgumentException>(()=>c.AcceptAcknowledgement(r,a,bad=="headers"?"public":"no-store",WorldBossAuthorityRequest.Version));Assert.AreEqual(before,c.CaptureLocal());}
  [Test] public void RestoreRejectsAlteredOriginalRequestHeader(){using var c=Open();Start(c);var saved=JObject.Parse(c.CaptureLocal());saved["pending"]["headers"]["Idempotency-Key"]="changed";Assert.Throws<ArgumentException>(()=>Restore(saved.ToString()));}
  [TestCase("한글")][TestCase("TOO_LONG")] public void InvalidTransportKeyCannotMutateController(string key){using var c=Open();c.PreviewRoute("p1r1","RIGHT");var before=c.CaptureLocal();Assert.Throws<ArgumentException>(()=>c.ConfirmPreview(key=="TOO_LONG"?new string('x',129):key));Assert.AreEqual(before,c.CaptureLocal());using var restored=Restore(c.CaptureLocal());Assert.IsNull(restored.PendingRequest);}
  [TestCase("future")][TestCase("missing-result")][TestCase("duplicate")][TestCase("wrong-owner")][TestCase("header-after-accept")]
  public void RestoreRejectsImpossibleOriginalAssociations(string bad){using var c=Open();Start(c);if(bad!="future")Apply(c,3);var saved=JObject.Parse(c.CaptureLocal());if(bad=="future")saved["pending"]["headers"]["X-World-Journal-Revision"]="999";else if(bad=="missing-result")saved["history"][0]["disposition"]="DEFINITIVE_409_ABSENT";else if(bad=="duplicate")((JArray)saved["history"]).Add(saved["history"][0].DeepClone());else if(bad=="wrong-owner")saved["history"][0]["request"]["body"]["commandId"]="other";else saved["history"][0]["request"]["headers"]["X-World-Journal-Revision"]="2";Assert.Throws<ArgumentException>(()=>Restore(saved.ToString()));}
  [TestCase(1)][TestCase(2)][TestCase(11)] public void ActualHonoOriginalAcknowledgementsPreserveExactReceipt(int i){using var c=Open();var r=Start(c);Ack(c,r,i);Equal(Read(i),c.OriginalAcknowledgement);Assert.AreEqual(1,c.State.Rail.Revision);Assert.IsNotNull(c.PendingRequest);}
  [Test] public void DefinitiveAbsentKeyRequiresNewKeyForNewIntent(){using var c=Open();var r=Start(c);c.AcceptFailure(r,409,(JObject)Trace(5)["response"],"no-store",WorldBossAuthorityRequest.Version);Apply(c,0);c.PreviewRoute("p1r1","RIGHT");var before=c.CaptureLocal();Assert.Throws<ArgumentException>(()=>c.ConfirmPreview("route"));Assert.AreEqual(before,c.CaptureLocal());Assert.AreEqual("fresh",(string)c.ConfirmPreview("fresh").Body["commandId"]);}
  [Test] public void ClientCannotSendHpOrHealthApply(){var body=(JObject)Trace(1)["request"]["body"].DeepClone();body["hp"]=1;Assert.Throws<ArgumentException>(()=>new WorldBossAuthorityRequest("trial","LOCAL_GEO",body,1));var r=new WorldBossAuthorityRequest("trial","LOCAL_GEO");Assert.IsFalse(r.Path.Contains("apply"));Assert.IsNull(r.Body);}
  [Test] public void CallbackReplacementUnbindAndDisposeDoNotDuplicateCommands(){var c=Open();int old=0,current=0,changes=0;c.Bind(_=>old++,null);c.Bind(_=>current++,()=>changes++);Start(c);Assert.AreEqual(0,old);Assert.AreEqual(1,current);c.Unbind();int prior=changes;c.RetryOriginal();Assert.AreEqual(1,current);Assert.AreEqual(prior,changes);c.Dispose();c.Dispose();Assert.Throws<ObjectDisposedException>(()=>Apply(c,3));}
  [Test] public void ReentrantResponseCannotPublishDuringRequestDispatch(){using var c=Open();bool rejected=false;c.Bind(r=>{try{Ack(c,r);}catch(InvalidOperationException){rejected=true;}},null);Start(c);Assert.IsTrue(rejected);Assert.IsNull(c.OriginalAcknowledgement);Assert.AreEqual(1,c.State.Rail.Revision);}
  [Test] public void DisposeFromRequestCallbackStopsLaterNotifications(){var c=Open();int n=0;c.Bind(_=>c.Dispose(),()=>n++);c.PreviewRoute("p1r1","RIGHT");int prior=n;c.ConfirmPreview("route");Assert.AreEqual(prior,n);Assert.Throws<ObjectDisposedException>(()=>c.RequestRead());}
 }
}
#endif
